 public static byte[] BuildCave(long image,long cave){byte[] b=(byte[])Payload.Clone();
Buffer.BlockCopy(BitConverter.GetBytes(cave+32768L),0,b,60,8);
Buffer.BlockCopy(BitConverter.GetBytes(cave+4096L),0,b,70,8);
Buffer.BlockCopy(BitConverter.GetBytes(cave+768L),0,b,149,8);
Buffer.BlockCopy(BitConverter.GetBytes(image+112010949L),0,b,231,8);
Buffer.BlockCopy(BitConverter.GetBytes(image+112010968L),0,b,782,8);
return b;}
public static byte[] Config(long image){var b=new List<byte>();b.AddRange(BitConverter.GetBytes(image+0x1535830L));b.AddRange(BitConverter.GetBytes(image+0xd754c8L));b.AddRange(BitConverter.GetBytes((uint)1));b.AddRange(BitConverter.GetBytes((uint)0x494e4831));return b.ToArray();}

 [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr OpenProcess(uint access,bool inherit,int pid);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool CloseHandle(IntPtr h);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool ReadProcessMemory(IntPtr h,IntPtr a,byte[] b,IntPtr size,out IntPtr n);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool WriteProcessMemory(IntPtr h,IntPtr a,byte[] b,IntPtr size,out IntPtr n);
 [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr VirtualAllocEx(IntPtr h,IntPtr a,IntPtr size,uint type,uint protection);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool VirtualFreeEx(IntPtr h,IntPtr a,IntPtr size,uint type);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool VirtualProtectEx(IntPtr h,IntPtr a,IntPtr size,uint protection,out uint old);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool FlushInstructionCache(IntPtr h,IntPtr a,IntPtr size);
 static void Check(bool ok,string message){if(!ok)throw new InvalidOperationException(message+" (Win32 "+Marshal.GetLastWin32Error()+")");}
 static byte[] Read(IntPtr h,long a,int size){byte[] b=new byte[size];IntPtr n;Check(ReadProcessMemory(h,new IntPtr(a),b,new IntPtr(size),out n)&&n.ToInt64()==size,"Read memory");return b;}
 static void Write(IntPtr h,long a,byte[] b){IntPtr n;Check(WriteProcessMemory(h,new IntPtr(a),b,new IntPtr(b.Length),out n)&&n.ToInt64()==b.Length,"Write memory");}
 static bool Equal(byte[] a,byte[] b){if(a.Length!=b.Length)return false;for(int i=0;i<a.Length;i++)if(a[i]!=b[i])return false;return true;}
 static string Sha(string path){using(var s=SHA256.Create())using(var f=File.OpenRead(path))return BitConverter.ToString(s.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 static byte[] Redirect(long entry,long cave,int size){byte[] b=new byte[size];for(int i=0;i<size;i++)b[i]=0x90;b[0]=0xe9;Buffer.BlockCopy(BitConverter.GetBytes(checked((int)(cave-entry-5))),0,b,1,4);return b;}
 static void ProtectedWrite(IntPtr h,long entry,byte[] value,ref uint originalProtection){uint old;Check(VirtualProtectEx(h,new IntPtr(entry),new IntPtr(value.Length),RWX,out old),"Protect redirect");if(originalProtection==0)originalProtection=old;try{Write(h,entry,value);Check(FlushInstructionCache(h,new IntPtr(entry),new IntPtr(value.Length)),"Flush redirect");Check(Equal(Read(h,entry,value.Length),value),"Verify redirect");}finally{uint ignored;Check(VirtualProtectEx(h,new IntPtr(entry),new IntPtr(value.Length),originalProtection,out ignored),"Restore redirect protection");}}
 static IntPtr Allocate(IntPtr h,long image){for(long d=0x20000000;d<=0x60000000;d+=0x10000){var a=VirtualAllocEx(h,new IntPtr(image+d),new IntPtr(0x9000),0x3000,RW);if(a!=IntPtr.Zero)return a;}return IntPtr.Zero;}
 static Process Supported(int pid){var p=Process.GetProcessById(pid);if(!String.Equals(p.ProcessName,"Zoe2Mars",StringComparison.OrdinalIgnoreCase)||Sha(p.MainModule.FileName)!=ExpectedExe)throw new Exception("Unsupported game process/executable");return p;}
 static void Attach(int pid){
  var process=Supported(pid);long image=process.MainModule.BaseAddress.ToInt64();IntPtr h=OpenProcess(0x438,false,pid);Check(h!=IntPtr.Zero,"Open game process");
  IntPtr allocation=IntPtr.Zero;bool committed=false,uncertain=false;var attempted=new List<Hook>();
  try{
   foreach(var hook in Hooks)if(!Equal(Read(h,image+hook.Entry-ImageBase,hook.Stolen.Length),hook.Stolen))throw new Exception("Native Viper bytes differ or a conflicting helper is active at "+hook.Entry.ToString("x"));
   allocation=Allocate(h,image);Check(allocation!=IntPtr.Zero,"Allocate Viper code/configuration");long cave=allocation.ToInt64();byte[] code=BuildCave(image,cave),config=Config(image);
   Write(h,cave,code);Write(h,cave+0x8000,config);Check(Equal(Read(h,cave,code.Length),code)&&Equal(Read(h,cave+0x8000,config.Length),config),"Verify Viper payload");
   uint old;Check(VirtualProtectEx(h,allocation,new IntPtr(0x8000),RX,out old),"Protect Viper code");Check(FlushInstructionCache(h,allocation,new IntPtr(code.Length)),"Flush Viper code");
   foreach(var hook in Hooks){attempted.Add(hook);ProtectedWrite(h,image+hook.Entry-ImageBase,Redirect(image+hook.Entry-ImageBase,cave+hook.Cave,hook.Stolen.Length),ref hook.Protection);}
   committed=true;Console.WriteLine("Vic Viper movement, arena reachability and native clone-death guards active. Original Mars behaviour retained. Disk executable unchanged.");
  }catch(Exception failure){
   for(int i=attempted.Count-1;i>=0;i--){var hook=attempted[i];try{ProtectedWrite(h,image+hook.Entry-ImageBase,hook.Stolen,ref hook.Protection);}catch{uncertain=true;}}
   if(uncertain)throw new Exception("Viper attachment failed and rollback could not be verified. Close the game. "+failure.Message);
   throw;
  }finally{if(allocation!=IntPtr.Zero&&!committed&&!uncertain)VirtualFreeEx(h,allocation,IntPtr.Zero,0x8000);CloseHandle(h);}
 }
 static void SelfTest(string folder){Directory.CreateDirectory(folder);foreach(long image in new long[]{ImageBase,0x180000000,0x7ff600000000})foreach(long offset in new long[]{0x20000000,0x20010000,0x60000000}){long cave=image+offset;byte[] b=BuildCave(image,cave),c=Config(image);if(c.Length!=24||b.Length>=0x8000)throw new Exception("Viper payload bounds");File.WriteAllBytes(Path.Combine(folder,"inhert-"+image.ToString("x")+"-"+offset.ToString("x")+".bin"),b);File.WriteAllBytes(Path.Combine(folder,"config-"+image.ToString("x")+".bin"),c);}Console.WriteLine("Viper payload fixtures at three bases and three cave offsets; no game opened.");}
 public static int Main(string[] args){try{if(args.Length==2&&args[0]=="--self-test"){SelfTest(args[1]);return 0;}if(args.Length==2&&args[0]=="--attach-menu"){Attach(Int32.Parse(args[1]));return 0;}if(args.Length==3&&args[0]=="--capture-status"){throw new Exception("Use the encounter recorder for Inhert status");return 0;}Console.WriteLine("--self-test folder; --attach-menu PID; --capture-status PID output.json");return 0;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}}
}

